// The tests in this file check the files that values.yaml documents: they write each file
// in the documented format, at its documented path below a temporary directory, and read it
// with the code that the Checker uses for it. Certificates and keys are generated by the
// tests.

// fileRoot is a temporary directory that stands for the root directory of the container:
// the files of the documented paths, such as /etc/otel/tls.crt, are created below it.
type fileRoot string

func newFileRoot(t *testing.T) fileRoot {
	t.Helper()
	return fileRoot(t.TempDir())
}

// path returns the path below the root for a path in the container.
func (r fileRoot) path(containerPath string) string {
	return filepath.Join(string(r), containerPath)
}

// write creates the file of a path in the container.
func (r fileRoot) write(t *testing.T, containerPath string, content []byte) {
	t.Helper()

	path := r.path(containerPath)

	err := os.MkdirAll(filepath.Dir(path), 0o700)
	if err == nil {
		err = os.WriteFile(path, content, 0o600)
	}

	if err != nil {
		t.Fatal(err)
	}
}

// ref returns the value reference with its file below the root.
func (r fileRoot) ref(t *testing.T, ref commoncfg.SourceRef) commoncfg.SourceRef {
	t.Helper()

	if ref.Source != commoncfg.FileSourceValue {
		t.Fatalf("want a file reference, got %+v", ref)
	}

	ref.File.Path = r.path(ref.File.Path)

	return ref
}

// collector starts an HTTPS test server with the certificate that requires a client
// certificate issued by a CA in clientCAs, and returns its URL with the host name localhost.
func collector(t *testing.T, cert tls.Certificate, clientCAs *x509.CertPool) string {
	t.Helper()

	server := httptest.NewUnstartedServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
	server.TLS = &tls.Config{
		Certificates: []tls.Certificate{cert},
		ClientAuth:   tls.RequireAndVerifyClientCert,
		ClientCAs:    clientCAs,
		MinVersion:   tls.VersionTLS12,
	}
	server.StartTLS()
	t.Cleanup(server.Close)

	_, port, err := net.SplitHostPort(server.Listener.Addr().String())
	if err != nil {
		t.Fatal(err)
	}

	return "https://localhost:" + port
}

// TestFilesTelemetry checks the files of the telemetry examples of values.yaml
// (values-all-config*.yaml), read with the common-sdk functions that the OpenTelemetry
// exporters of the Checker use.
func TestFilesTelemetry(t *testing.T) {
	pki := newTestPKI(t)

	// mtlsConfig writes the client files of the mtls settings and loads them.
	mtlsConfig := func(t *testing.T, mtls commoncfg.MTLS, format keyFormat) *tls.Config {
		t.Helper()

		root := newFileRoot(t)
		crt, key, ca := pki.clientFiles(t, format)
		root.write(t, mtls.Cert.File.Path, crt)
		root.write(t, mtls.CertKey.File.Path, key)
		mtls.Cert = root.ref(t, mtls.Cert)
		mtls.CertKey = root.ref(t, mtls.CertKey)

		if mtls.ServerCA != nil {
			root.write(t, mtls.ServerCA.File.Path, ca)
			serverCA := root.ref(t, *mtls.ServerCA)
			mtls.ServerCA = &serverCA
		}

		mtls.RootCAs = slices.Clone(mtls.RootCAs)
		for i, rootCA := range mtls.RootCAs {
			root.write(t, rootCA.File.Path, ca)
			mtls.RootCAs[i] = root.ref(t, rootCA)
		}

		return must(commoncfg.LoadMTLSConfig(&mtls))(t)
	}

	get := func(t *testing.T, client *http.Client, url string) error {
		t.Helper()

		resp, err := client.Get(url) //nolint:noctx // test request
		if err != nil {
			return err
		}

		return resp.Body.Close()
	}

	tlsClient := func(tlsConfig *tls.Config) *http.Client {
		return &http.Client{Transport: &http.Transport{TLSClientConfig: tlsConfig}}
	}

	t.Run("mtls with serverCa", func(t *testing.T) {
		mtls := loadValues(t, "-f", "testdata/values-all-config.yaml").Telemetry.Traces.SecretRef.MTLS
		if mtls.ServerCA == nil {
			t.Fatal("the example has no serverCa")
		}

		url := collector(t, pki.server(t, "localhost"), pki.rootPool())

		for _, format := range keyFormats {
			t.Run("tls.key "+format.name, func(t *testing.T) {
				err := get(t, tlsClient(mtlsConfig(t, mtls, format)), url)
				if err != nil {
					t.Fatal(err)
				}
			})
		}
	})

	t.Run("mtls with rootCAs and serverName", func(t *testing.T) {
		mtls := loadValues(t, "-f", "testdata/values-all-config-alt2.yaml").Telemetry.Traces.SecretRef.MTLS
		if len(mtls.RootCAs) != 1 || mtls.Attributes == nil ||
			mtls.Attributes.ServerName != "otel-collector.example.com" {
			t.Fatalf("the example has not one rootCAs entry and serverName: %+v", mtls)
		}

		url := collector(t, pki.server(t, "otel-collector.example.com"), pki.rootPool())

		err := get(t, tlsClient(mtlsConfig(t, mtls, keyFormats[1])), url)
		if err != nil {
			t.Fatal(err)
		}
	})

	// apiTokenHeader sends a request with the client of the api-token reference and returns
	// the Authorization header that the server received.
	apiTokenHeader := func(t *testing.T, ref commoncfg.SourceRef) (string, error) {
		t.Helper()

		var authorization string

		server := httptest.NewServer(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
			authorization = r.Header.Get("Authorization")
		}))
		t.Cleanup(server.Close)

		err := get(t, must(commonhttp.NewClientFromAPIToken(&ref))(t), server.URL)

		return authorization, err
	}

	t.Run("api-token file", func(t *testing.T) {
		apiToken := loadValues(t, "-f", "testdata/values-all-config.yaml").Telemetry.Metrics.SecretRef.APIToken

		root := newFileRoot(t)
		root.write(t, apiToken.File.Path, []byte("<token>"))

		got, err := apiTokenHeader(t, root.ref(t, apiToken))
		if err != nil || got != "Api-Token <token>" {
			t.Errorf("got %q, %v", got, err)
		}

		// A trailing newline is part of the token, and the request fails.
		root.write(t, apiToken.File.Path, []byte("<token>\n"))

		_, err = apiTokenHeader(t, root.ref(t, apiToken))
		if err == nil || !strings.Contains(err.Error(), "invalid header field value") {
			t.Errorf("token with a newline: got %v", err)
		}
	})

	t.Run("api-token from a JSON file", func(t *testing.T) {
		apiToken := loadValues(t, "-f", "testdata/values-all-config-alt1.yaml").Telemetry.Logs.SecretRef.APIToken

		root := newFileRoot(t)
		// The example content of /etc/otel/otel.json in values.yaml.
		root.write(t, apiToken.File.Path, []byte(`{ "token": "<token>" }`))

		got, err := apiTokenHeader(t, root.ref(t, apiToken))
		if err != nil || got != "Api-Token <token>" {
			t.Errorf("got %q, %v", got, err)
		}
	})

	t.Run("basic password", func(t *testing.T) {
		basic := loadValues(t, "-f", "testdata/values-all-config-alt1.yaml").Telemetry.Traces.SecretRef.Basic

		root := newFileRoot(t)
		root.write(t, basic.Password.File.Path, []byte("<password>"))

		password := must(commoncfg.LoadValueFromSourceRef(root.ref(t, basic.Password)))(t)
		if string(password) != "<password>" {
			t.Errorf("got %q", password)
		}
	})
}

// TestFilesMountExample renders the chart with the example of extraVolumes and
// extraVolumeMounts in values.yaml, and checks that the files of the telemetry examples are
// in the mounted Secret.
func TestFilesMountExample(t *testing.T) {
	example := "extraVolumes:\n" + valuesComment(t, "Example of the volume:") +
		"extraVolumeMounts:\n" + valuesComment(t, "Example of the mount for the volume above:")

	type mounts struct {
		Spec struct {
			Template struct {
				Spec struct {
					Containers []struct {
						VolumeMounts []struct {
							Name      string `yaml:"name"`
							MountPath string `yaml:"mountPath"`
							ReadOnly  bool   `yaml:"readOnly"`
						} `yaml:"volumeMounts"`
					} `yaml:"containers"`
					Volumes []struct {
						Name   string `yaml:"name"`
						Secret *struct {
							SecretName  string `yaml:"secretName"`
							DefaultMode int    `yaml:"defaultMode"`
						} `yaml:"secret"`
					} `yaml:"volumes"`
				} `yaml:"spec"`
			} `yaml:"template"`
		} `yaml:"spec"`
	}

	pod := object[mounts](t, render(t, "-f", writeValues(t, example)), "Deployment").Spec.Template.Spec

	var secret string

	for _, v := range pod.Volumes {
		if v.Name == "otel-credentials" && v.Secret != nil && v.Secret.DefaultMode == 0o440 {
			secret = v.Secret.SecretName
		}
	}

	if secret != "checker-otel" {
		t.Fatalf("no volume otel-credentials of the Secret checker-otel with mode 0440: %+v", pod.Volumes)
	}

	mounted := false

	for _, m := range pod.Containers[0].VolumeMounts {
		if m.Name == "otel-credentials" && m.MountPath == "/etc/otel" && m.ReadOnly {
			mounted = true
		}
	}

	if !mounted {
		t.Errorf("otel-credentials is not mounted read-only at /etc/otel: %+v", pod.Containers[0].VolumeMounts)
	}
}
